[
  {
    "title": "複利的意思",
    "body": "複利是把已累積的利息或報酬加入本金，下一期再對新的總額計算。",
    "examples": [
      "本金100元，年利率10%。第一年後為110元；第二年按110元計息，變成121元。"
    ]
  },
  {
    "title": "為什麼時間重要",
    "body": "複利需要時間累積；越早開始，利息或報酬參與計算的期數越多，成長通常越明顯。",
    "examples": [
      "同樣每年獲得報酬，資金持續累積多年，後期的增長會建立在先前已累積的金額上。"
    ]
  }
]
